// energy/degradation sketch for: Battery Lifecycle Simulator
let c = 1.0; const samples = [];
for (let i = 0; i < 641; i++) { c *= 0.9999; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 641, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

